//
// During tests the database uses a shared in-memory backing store
// (`file::memory:?cache=shared`). The in-memory database lives for as long as
// at least one client connection to it stays open, so leaking a client between
// test suites leaks schema and rows into the "fresh" database created after a
// module cache reset. These helpers track every client opened during testing so
// they can all be closed, guaranteeing the next `getDb()` starts from an empty
// database.

/** Minimal shape of a client the registry needs to close. */
type CloseableClient = {
  close: () => any;
  execute: (sql: string) => Promise<any>;
};

/** Shape of a client that can have its schema reset. */
type ResettableClient = {
  close: () => any;
  execute: (sql: string) => Promise<{ rows: Array<{ type: string; name: string }> }>;
};

// The registry is stored on `globalThis` so it survives module cache resets
// (e.g. Vitest's `vi.resetModules()`). Without this, resetting the module cache
// would create a brand-new empty registry that no longer knows about clients
// opened by the previous module instance, so those clients (and the in-memory
// database they keep alive) would never be closed.
const REGISTRY_KEY = Symbol.for('promptfoo.testDatabaseClients');

type GlobalWithRegistry = typeof globalThis & {
  [REGISTRY_KEY]?: Set<CloseableClient>;
};

function getRegistry(): Set<CloseableClient> {
  const globalWithRegistry = globalThis as GlobalWithRegistry;
  if (!globalWithRegistry[REGISTRY_KEY]) {
    globalWithRegistry[REGISTRY_KEY] = new Set<CloseableClient>();
  }
  return globalWithRegistry[REGISTRY_KEY];
}

/**
 * Register a database client in the global test registry so that
 * {@link closeTestDatabaseClients} can later close it. Called from `getDb()`
 * when `IS_TESTING` is set.
 */
export function registerTestDatabaseClient(client: CloseableClient): void {
  getRegistry().add(client);
}

/**
 * Close every registered test database client and clear the registry. After
 * this resolves the registry is empty, so a subsequent module cache reset plus
 * re-import produces a fully isolated database with no shared schema or data.
 */
export async function closeTestDatabaseClients(): Promise<void> {
  const registry = getRegistry();
  const clients = Array.from(registry);
  registry.clear();

  for (const client of clients) {
    try {
      await client.close();
    } catch {
      // Ignore errors closing individual clients; the goal is to drop every
      // reference so the shared in-memory database can be reclaimed.
    }
  }
}

/** Wrap a SQL identifier in double-quotes, doubling any embedded quotes. */
function quoteIdentifier(name: string): string {
  return `"${name.replace(/"/g, '""')}"`;
}

/**
 * Reset the schema of a database client by dropping all user-created tables,
 * views, and triggers (but not indexes). The final statement executed is always
 * `PRAGMA foreign_keys = ON`, even if a drop fails.
 */
export async function resetTestDatabaseClient(client: ResettableClient): Promise<void> {
  try {
    // Disable foreign key enforcement so tables can be dropped in any order.
    await client.execute('PRAGMA foreign_keys = OFF');

    const result = await client.execute(
      "SELECT type, name FROM sqlite_master WHERE type IN ('table', 'view', 'trigger') AND name NOT LIKE 'sqlite_%'",
    );

    for (const { type, name } of result.rows) {
      const quoted = quoteIdentifier(name);
      if (type === 'table') {
        await client.execute(`DROP TABLE IF EXISTS ${quoted}`);
      } else if (type === 'view') {
        await client.execute(`DROP VIEW IF EXISTS ${quoted}`);
      } else if (type === 'trigger') {
        await client.execute(`DROP TRIGGER IF EXISTS ${quoted}`);
      }
    }
  } finally {
    // Always re-enable foreign key enforcement as the final statement.
    await client.execute('PRAGMA foreign_keys = ON');
  }
}
